1	package main
2	
3	import (
4		"context"
5		"fmt"
6		"path/filepath"
7		"strings"
8	
9		"github.com/u7k4rs6/Umbra/umbra/internal/checkpoint"
10		"github.com/u7k4rs6/Umbra/umbra/internal/graph"
11		"github.com/u7k4rs6/Umbra/umbra/internal/report"
12		"github.com/u7k4rs6/Umbra/umbra/internal/runner"
13		"github.com/u7k4rs6/Umbra/umbra/internal/shadow"
14	)
15	
16	// execute selects tests, runs them through verify with a baseline, then sweeps
17	// the full suite and explains every test the selection missed.
18	func execute(ctx context.Context, o *Options, run runner.Runner, pair *checkpoint.Pair, a *report.Analysis, st *pipelineState) error {
19		if o.Run == "none" {
20			return nil
21		}
22	
23		runnerArgv, err := SplitWords(o.Test)
24		if err != nil {
25			return err
26		}
27		if len(runnerArgv) == 0 {
28			return fmt.Errorf("the test runner is empty")
29		}
30	
31		// The runner is echoed before anything runs, which is the only guard
32		// against a destructive --test and is stated as such in the README.
33		fmt.Printf("running  %s\n", strings.Join(runnerArgv, " "))
34	
35		cands, notRunnable := shadow.SelectTests(a.Nodes, st.Field, st.RelMap, st.SourceIDs, o.Run, st.TestRoot)
36		a.Execution.Selected = shadow.IDs(cands)
37		a.Execution.NotRunnable = notRunnable
38	
39		if len(cands) == 0 {
40			if a.Audit {
41				return sweep(ctx, o, run, pair, a, st, runnerArgv, map[string]bool{})
42			}
43			return nil
44		}
45	
46		baseRepo, headRepo := testRepo(pair.Base, st.TestRoot), testRepo(pair.Head, st.TestRoot)
47		req := graph.VerifyRequest{
48			BaseRepo:     baseRepo,
49			HeadRepo:     headRepo,
50			Runner:       runnerArgv,
51			TestIDs:      a.Execution.Selected,
52			BaselinePath: filepath.Join(pair.Dir(), "baseline.json"),
53		}
54		v, cmds, err := graph.Verify(ctx, run, req)
55		if err != nil {
56			return fmt.Errorf("running the selected tests: %w", err)
57		}
58		a.Commands = append(a.Commands, scrubAll(st, cmds)...)
59	
60		a.Execution.NewFailures = v.NewlyFailing
61		a.Execution.Fixed = v.NewlyPassing
62		a.Execution.PreExisting = v.PreExisting
63		a.Execution.Verdict = v.Line
64		a.Execution.Degraded = v.Degraded
65		if v.TimedOut {
66			a.Notes = append(a.Notes, "the selected tests were cut short by the ten minute timeout")
67		}
68	
69		attachOutcomes(a, cands, v)
70	
71		if !a.Audit {
72			return nil
73		}
74		selected := map[string]bool{}
75		for _, id := range a.Execution.Selected {
76			selected[id] = true
77		}
78		return sweep(ctx, o, run, pair, a, st, runnerArgv, selected)
79	}
80	
81	// sweep runs the whole suite once and explains every changed test the
82	// selection did not choose.
83	func sweep(ctx context.Context, o *Options, run runner.Runner, pair *checkpoint.Pair, a *report.Analysis, st *pipelineState, runnerArgv []string, selected map[string]bool) error {
84		req := graph.VerifyRequest{
85			BaseRepo:     testRepo(pair.Base, st.TestRoot),
86			HeadRepo:     testRepo(pair.Head, st.TestRoot),
87			Runner:       runnerArgv,
88			BaselinePath: filepath.Join(pair.Dir(), "sweep.json"),
89			Timeout:      runner.SweepTimeout,
90		}
91		v, cmds, err := graph.Verify(ctx, run, req)
92		if err != nil {
93			return fmt.Errorf("running the full sweep: %w", err)
94		}
95		a.Commands = append(a.Commands, scrubAll(st, cmds)...)
96		a.Execution.Sweep = true
97		a.Execution.SweepCut = v.TimedOut
98	
99		changed := append(append([]string(nil), v.NewlyFailing...), v.NewlyPassing...)
100		leaks := shadow.Forensics(changed, shadow.ForensicsInput{
101			Field:         st.Field,
102			RelMap:        st.RelMap,
103			SourceIDs:     st.SourceIDs,
104			CoChangeFiles: st.CoChangeFiles,
105			Selected:      selected,
106			MaxDepth:      o.Depth,
107			RepoRelRoot:   st.TestRoot,
108		})
109		for _, l := range leaks {
110			a.Execution.Leaks = append(a.Execution.Leaks, report.Leak{Test: l.Test, Reason: l.Reason})
111		}
112	
113		// The sweep also finds failures the selection never ran. Fold them in so
114		// the report does not under-count what the change broke.
115		known := map[string]bool{}
116		for _, id := range a.Execution.NewFailures {
117			known[id] = true
118		}
119		for _, id := range v.NewlyFailing {
120			if !known[id] {
121				a.Execution.NewFailures = append(a.Execution.NewFailures, id)
122				known[id] = true
123			}
124		}
125		return nil
126	}
127	
128	// attachOutcomes marks each test node with what happened, and carries a
129	// failure onto every shadowed node on that test's path to a source.
130	func attachOutcomes(a *report.Analysis, cands []shadow.Candidate, v graph.Verdict) {
131		failed := map[string]bool{}
132		for _, id := range v.NewlyFailing {
133			failed[id] = true
134		}
135		// A test that was already failing before the change is still failing. It
136		// is not a crack, because this change did not break it, but calling it a
137		// pass would be a lie.
138		preExisting := map[string]bool{}
139		for _, id := range v.PreExisting {
140			preExisting[id] = true
141		}
142		for _, c := range cands {
143			switch {
144			case failed[c.ID], preExisting[c.ID]:
145				c.Node.Result = shadow.OutcomeFail
146			case v.Degraded:
147				// Without per-test ids there is no per-test outcome to report.
148				c.Node.Result = shadow.OutcomeNotRun
149			default:
150				c.Node.Result = shadow.OutcomePass
151			}
152		}
153	
154		// A failing probe is evidence about every shadowed node it passes through.
155		for _, c := range cands {
156			if !failed[c.ID] {
157				continue
158			}
159			for _, n := range a.Nodes {
160				if !n.Shadowed() || n.Symbol.ID == c.Node.Symbol.ID {
161					continue
162				}
163				if onPath(n.Symbol.ID, c.Node.Path) {
164					n.Tests = append(n.Tests, shadow.TestRef{ID: c.ID, Symbol: c.Node.Symbol.ID, Outcome: shadow.OutcomeFail})
165				}
166			}
167		}
168	}
169	
170	func onPath(id string, path []string) bool {
171		for _, p := range path {
172			if p == id {
173				return true
174			}
175		}
176		return false
177	}
178	
179	// scrubAll puts the verify commands through the same scrubber as every other
180	// recorded command.
181	//
182	// They used to be appended raw, so a report carried the absolute path of the
183	// worktree the tests ran in. Every other command in the list was scrubbed,
184	// which is why it went unnoticed until a real report was committed and the
185	// artifacts test read it.
186	func scrubAll(st *pipelineState, cmds []string) []string {
187		if st == nil || st.Scrub == nil {
188			return cmds
189		}
190		out := make([]string, 0, len(cmds))
191		for _, c := range cmds {
192			out = append(out, st.Scrub.Clean(c))
193		}
194		return out
195	}
196	
197	// testRepo returns the directory the runner should run in. The fixture app
198	// lives in a subdirectory, so tests run there rather than at the repository
199	// root.
200	func testRepo(worktree, relRoot string) string {
201		if worktree == "" {
202			return ""
203		}
204		if relRoot == "" {
205			return worktree
206		}
207		return filepath.Join(worktree, filepath.FromSlash(relRoot))
208	}
