// capitalise raises the first letter of a shared sentence so it can be used
// both mid-line in the table and as a sentence in the packet.
func capitalise(s string) string {
	if s == "" {
		return s
	}
	r := []rune(s)
	if r[0] >= 'a' && r[0] <= 'z' {
		r[0] = r[0] - 'a' + 'A'
	}
	return string(r)
