cd /tmp/claude-1000 && python3 - <<'PY'
import json, collections
syms={}; rels=[]
for l in open('s.ndjson'):
    l=l.strip()
    if not l: continue
    try: r=json.loads(l)
    except: continue
    if r.get('record_type')=='symbol': syms[r['id']]=r
    elif r.get('record_type')=='relation': rels.append(r)

IN=collections.defaultdict(list)
for r in rels: IN[r['to_id']].append(r)

CALLS={'CALLS','ASYNC_CALLS','OVERRIDES','INHERITS','EXTENDS','IMPLEMENTS','CONSTRUCTS'}
def qn(i): return syms.get(i,{}).get('qualified_name') or i.split(':')[-1]

def find(q):
    return [i for i,s in syms.items() if s.get('qualified_name')==q]

sources = find('wrap_text')+find('HelpFormatter')+find('HelpFormatter.write_usage')
print('sources:', [qn(s) for s in sources])

# BFS following CALLS-family to any depth, other families one hop, as Umbra does.
def bfs(maxdepth):
    best={}
    for src in sources:
        seen={src}
        q=[(src,0,[src])]
        while q:
            cur,d,path=q.pop(0)
            for e in IN[cur]:
                fam_calls = e['type'] in CALLS
                if d>=1 and not fam_calls: continue
                if fam_calls and d>=maxdepth: continue
                nxt=e['from_id']
                if nxt in seen or nxt in sources: continue
                seen.add(nxt)
                nd=d+1
                if nxt not in best or nd<best[nxt][0]:
                    best[nxt]=(nd, e['type'], path+[nxt])
                q.append((nxt,nd,path+[nxt]))
    return best

for depth in (2,3,4,6):
    b=bfs(depth)
    show=[k for k in b if qn(k)=='UsageError.show']
    tests=[k for k in b if syms.get(k,{}).get('file_path','').startswith('tests/')]
    print(f'depth {depth}: {len(b)} dependents, UsageError.show present: {bool(show)}, test symbols: {len(tests)}')
    if tests and depth<=4:
        for t in sorted(tests, key=lambda k: b[k][0])[:12]:
            print('    ', qn(t), syms[t]['file_path'], 'depth', b[t][0], b[t][1])
PY

