#!/usr/bin/env python3
"""Finding B: does Graph produce an edge for self.x.y() ?

Method. From the snapshot, index every CALLS edge by the exact source line its
evidence points at:

    for r in snap where record_type == "relation" and type == "CALLS":
        for e in r["evidence"] where e["kind"] in ("call_site","imported_call_site"):
            index[(e["file_path"], e["start_line"])].append(r)

Then scan the repository's non-test .py files for two call shapes and look each
occurrence up by its own line:

    chain  :  self.<attr>.<method>(      e.g. self.ctx.get_usage()
    direct :  self.<method>(             e.g. self.format_message()

The direct sample is the control: it isolates the attribute chain rather than
"self".
"""
import json, re, sys, os, collections, random

CHAIN  = re.compile(r"self\.([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(")
DIRECT = re.compile(r"(?<![.\w])self\.([A-Za-z_]\w*)\s*\(")

def index_calls(snap):
    syms, ext = {}, {}
    idx = collections.defaultdict(list)
    for l in open(snap):
        l = l.strip()
        if not l: continue
        try: r = json.loads(l)
        except ValueError: continue
        t = r.get("record_type")
        if t == "symbol": syms[r["id"]] = r
        elif t == "external": ext[r["id"]] = r
        elif t == "relation" and r.get("type") == "CALLS":
            for e in (r.get("evidence") or []):
                if e.get("kind") in ("call_site", "imported_call_site") and e.get("start_line"):
                    idx[(e.get("file_path"), e["start_line"])].append(r)
    return syms, ext, idx

def describe(r, syms, ext):
    to = r["to_id"]
    if to in syms:
        s = syms[to]
        return f"SAME-REPO {s.get('qualified_name')} ({s['file_path']})"
    if to in ext:
        return f"external  {ext[to].get('value')}"
    return f"?         {to}"

def scan(repo, pkgdir, snap, want=12, seed=7):
    syms, ext, idx = index_calls(snap)
    chain_hits, direct_hits = [], []
    for root, dirs, files in os.walk(os.path.join(repo, pkgdir)):
        dirs[:] = [d for d in dirs if d not in ("__pycache__", ".git")]
        for fn in sorted(files):
            if not fn.endswith(".py"): continue
            full = os.path.join(root, fn)
            rel = os.path.relpath(full, repo)
            for n, line in enumerate(open(full, encoding="utf-8", errors="replace"), 1):
                for m in CHAIN.finditer(line):
                    chain_hits.append((rel, n, f"self.{m.group(1)}.{m.group(2)}()"))
                if not CHAIN.search(line):
                    for m in DIRECT.finditer(line):
                        direct_hits.append((rel, n, f"self.{m.group(1)}()"))
    rnd = random.Random(seed)
    def sample(hits):
        return hits if len(hits) <= want else rnd.sample(hits, want)
    def resolve(hits):
        rows, res = [], collections.Counter()
        for rel, n, expr in sorted(sample(hits)):
            edges = idx.get((rel, n), [])
            if not edges:
                rows.append((rel, n, expr, "NO EDGE", ""))
                res["no edge"] += 1
            for e in edges:
                d = describe(e, syms, ext)
                rows.append((rel, n, expr, d, f"{e.get('resolution')}/{e.get('confidence')}"))
                res["same-repo" if d.startswith("SAME") else "external"] += 1
        return rows, res
    return resolve(chain_hits), resolve(direct_hits), len(chain_hits), len(direct_hits)

if __name__ == "__main__":
    repos = [("click", os.path.expanduser("~/umbra-experiment/click"), "src/click", "/tmp/claude-1000/snaps/click.ndjson"),
             ("httpx", os.path.expanduser("~/umbra-experiment/httpx"), "httpx", "/tmp/claude-1000/snaps/httpx.ndjson"),
             ("pre-commit", os.path.expanduser("~/umbra-experiment/pre-commit"), "pre_commit", "/tmp/claude-1000/snaps/pre-commit.ndjson")]
    for name, repo, pkg, snap in repos:
        (crows, cres), (drows, dres), ctot, dtot = scan(repo, pkg, snap)
        print(f"===== {name}   chain occurrences in source: {ctot}   direct self calls: {dtot}")
        print(f"  -- self.x.y() sample ({len(crows)} rows) --")
        for rel, n, expr, d, meta in crows:
            print(f"     {rel}:{n:<5} {expr:34} {d:52} {meta}")
        print(f"     tally: {dict(cres)}")
        print(f"  -- self.y() control sample ({len(drows)} rows) --")
        for rel, n, expr, d, meta in drows:
            print(f"     {rel}:{n:<5} {expr:34} {d:52} {meta}")
        print(f"     tally: {dict(dres)}")
        print()
