#!/usr/bin/env python3
"""Finding B, corrected method.

Snapshot CALLS evidence points at the CALLING FUNCTION's start line, not at the
call expression (internal/graph/snapshot.go says so). So a call site cannot be
looked up by its own line. Instead:

  1. Build spans: for each snapshot symbol, (file_path, start_line, end_line).
  2. For a call site at file:line, the enclosing symbol is the smallest span
     containing that line.
  3. The call "resolved" if that enclosing symbol has an outgoing CALLS edge
     whose target's bare name equals the called method name.

Sound in one direction: if no out-edge of the enclosing function carries the
called name, Graph produced no edge for that call. Two call sites of the same
name in one function collapse, which is why the tally counts distinct sites.
"""
import json, re, os, collections, random

CHAIN  = re.compile(r"self\.([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(")
DIRECT = re.compile(r"(?<![.\w])self\.([A-Za-z_]\w*)\s*\(")

def load(snap):
    syms, ext, out = {}, {}, collections.defaultdict(list)
    for l in open(snap):
        l = l.strip()
        if not l: continue
        try: r = json.loads(l)
        except ValueError: continue
        t = r.get("record_type")
        if t == "symbol": syms[r["id"]] = r
        elif t == "external": ext[r["id"]] = r
        elif t == "relation" and r.get("type") in ("CALLS", "CONSTRUCTS"):
            out[r["from_id"]].append(r)
    byfile = collections.defaultdict(list)
    for i, s in syms.items():
        byfile[s["file_path"]].append(i)
    return syms, ext, out, byfile

def enclosing(syms, byfile, path, line):
    best = None
    for i in byfile.get(path, []):
        s = syms[i]
        a, b = s.get("start_line") or 0, s.get("end_line") or 0
        if a <= line <= b:
            if best is None or (b - a) < (best[1] - best[0]):
                best = (a, b, i)
    return best[2] if best else None

def target_name(r, syms, ext):
    to = r["to_id"]
    if to in syms:
        return syms[to].get("name"), "SAME-REPO", syms[to].get("qualified_name"), syms[to]["file_path"]
    if to in ext:
        v = str(ext[to].get("value", ""))
        return v.split(".")[-1], "external", v, ""
    return None, "?", to, ""

def run(name, repo, pkg, snap, want=12, seed=7):
    syms, ext, out, byfile = load(snap)
    chain, direct = [], []
    for root, dirs, files in os.walk(os.path.join(repo, pkg)):
        dirs[:] = [d for d in dirs if d not in ("__pycache__", ".git")]
        for fn in sorted(files):
            if not fn.endswith(".py"): continue
            full = os.path.join(root, fn); rel = os.path.relpath(full, repo)
            for n, line in enumerate(open(full, encoding="utf-8", errors="replace"), 1):
                for m in CHAIN.finditer(line):
                    chain.append((rel, n, m.group(1), m.group(2)))
                if not CHAIN.search(line):
                    for m in DIRECT.finditer(line):
                        direct.append((rel, n, None, m.group(1)))
    rnd = random.Random(seed)
    def check(hits, label):
        pick = hits if len(hits) <= want else rnd.sample(hits, want)
        rows, tally = [], collections.Counter()
        for rel, n, attr, meth in sorted(pick):
            enc = enclosing(syms, byfile, rel, n)
            hit = None
            for r in out.get(enc, []):
                tn, kind, qn, tf = target_name(r, syms, ext)
                if tn == meth:
                    hit = (kind, qn, tf, r.get("resolution"), r.get("confidence")); break
            expr = f"self.{attr}.{meth}()" if attr else f"self.{meth}()"
            if hit:
                rows.append((rel, n, expr, f"{hit[0]} {hit[1]}", f"{hit[3]}/{hit[4]}"))
                tally[hit[0]] += 1
            else:
                rows.append((rel, n, expr, "NO EDGE", ""))
                tally["no edge"] += 1
        return rows, tally
    return check(chain, "chain"), check(direct, "direct"), len(chain), len(direct)

if __name__ == "__main__":
    for name, repo, pkg in [("click", "click", "src/click"),
                            ("httpx", "httpx", "httpx"),
                            ("pre-commit", "pre-commit", "pre_commit")]:
        r = os.path.expanduser(f"~/umbra-experiment/{repo}")
        snap = f"/tmp/claude-1000/snaps/{name}.ndjson"
        (crows, ctal), (drows, dtal), ct, dt = run(name, r, pkg, snap)
        print(f"===== {name}    self.x.y() sites in source: {ct}    self.y() sites: {dt}")
        print("  -- self.x.y() chain sample --")
        for rel, n, e, d, meta in crows: print(f"     {rel}:{n:<5} {e:34} {d:46} {meta}")
        print(f"     tally: {dict(ctal)}")
        print("  -- self.y() control sample --")
        for rel, n, e, d, meta in drows: print(f"     {rel}:{n:<5} {e:34} {d:46} {meta}")
        print(f"     tally: {dict(dtal)}")
        print()
